package com.yihe.framework.ehr;

import java.util.*;
import org.springframework.stereotype.Service;
import static com.yihe.framework.ehr.EhrAccess.*;
import static com.yihe.framework.ehr.EhrService.*;
import static com.yihe.framework.ehr.HealthAgentTools.*;

/** A separate read-only catalog. No employee selector and no enterprise aggregate tool. */
@Service
public class MiniappAgentTools {
    final MiniappAgentStore store;final EhrRepository db;final EhrService ehr;
    public MiniappAgentTools(MiniappAgentStore store,EhrRepository db,EhrService ehr){this.store=store;this.db=db;this.ehr=ehr;}
    List<Object> catalog(){return Arrays.<Object>asList(
        spec("get_my_profile","读取当前已绑定职工本人的年龄、岗位和职业暴露背景，不需要姓名或工号。",map()),
        spec("list_my_reports","分页查看本人体检报告目录；确认状态和归档状态不同，未审核报告不能当成正式结果。",map("page",integer("页码",10000))),
        spec("get_my_report","读取本人报告原始指标、结论、医师建议及证据页码；每页60项，剩余项目必须继续分页或说明分析范围。候选报告必须由用户在当前请求明确选中。",map("report_id",string("从本人报告目录获得的ID"),"revision",integer("版本",10000),"page",integer("页码",10000))),
        spec("get_my_health_trends","查询本人已确认报告中同类检查结果，按核定日期排序。只提供原始值和单位，不混算不同单位或不同比较条件。",map("indicator",string("检查项目名称关键字，必填"),"page",integer("页码",10000))),
        spec("get_my_abnormal_items","查看本人当前报告中已有的异常标记。默认医生确认报告；用户明确选中的候选报告可核对，不是诊断。",map("indicator",string("项目关键字，不限则空字符串"),"page",integer("页码",10000))),
        spec("get_my_confirmed_risks","读取本人最近一次医生确认的健康风险评估及依据；没有评估不能当成低风险。",map()));}
    @SuppressWarnings("unchecked") void validate(String name,Map<String,Object> args){Map<String,Object> schema=null;for(Object o:catalog()){Map<String,Object> tool=(Map<String,Object>)o;if(name.equals(tool.get("name")))schema=(Map<String,Object>)tool.get("parameters");}require(schema!=null,403,"TOOL_NOT_ALLOWED：个人健康师未开放此工具");Map<String,Object> props=(Map<String,Object>)schema.get("properties");require(props.keySet().equals(args.keySet()),422,"工具参数缺失或含有未声明字段");for(String k:props.keySet()){Map<String,Object> r=(Map<String,Object>)props.get(k);Object v=args.get(k);if("integer".equals(r.get("type")))require(v instanceof Number&&((Number)v).doubleValue()==((Number)v).intValue()&&num(v)>=1&&num(v)<=num(r.get("maximum")),422,"工具页码无效");else require(v instanceof String&&((String)v).length()<=100,422,"工具参数无效");}}
    boolean selected(Map<String,Object> context,String rid,int rev){return rid.equals(text(context,"reportId"))&&context.get("revision") instanceof Number&&rev==num(context.get("revision"));}
    void context(MiniappAgentStore.Person p,Map<String,Object> c){store.check(p);if(!c.isEmpty()){require(c.keySet().equals(new HashSet<>(Arrays.asList("reportId","revision"))),422,"报告上下文只允许reportId、revision");require(text(c,"reportId").matches("[a-f0-9-]{36}")&&c.get("revision") instanceof Number&&num(c.get("revision"))>=1&&num(c.get("revision"))<=10000&&((Number)c.get("revision")).doubleValue()==num(c.get("revision")),422,"报告ID或版本无效");ehr.rawReport(p.actor,text(c,"reportId"),num(c.get("revision")),false);}}
    void source(MiniappAgentStore.Person p,String rid,int rev,Collection<?> pages,List<Object> sources){Map<String,Object> h=ehr.rawReport(p.actor,rid,rev,false);String key=rid+":"+rev;for(Object s:sources){Map<?,?> m=(Map<?,?>)s;if(key.equals(m.get("key"))){Map<String,Object> found=(Map<String,Object>)s;Set<Object> merged=new TreeSet<>((Collection<?>)found.get("pageNumbers"));merged.addAll(pages);found.put("pageNumbers",new ArrayList<>(merged));return;}}boolean published=db.count("SELECT COUNT(*) FROM a_report_publications WHERE report_id=? AND revision=? AND record_id=? AND scope_code=? AND data_mode=?",rid,rev,p.record,p.scope,p.mode)>0;sources.add(map("key",key,"reportId",rid,"revision",rev,"reviewStatus",h.get("review_status"),"published",published,"candidate",!"confirmed".equals(h.get("review_status")),"examDate",h.get("exam_date_verified"),"institution",h.get("institution_raw"),"pageNumbers",new ArrayList<>(pages),"detailPath","/ehr/miniapp/reports/"+rid+"/"+rev));}
    @SuppressWarnings("unchecked") Object execute(MiniappAgentStore.Person p,String name,Map<String,Object> b,Map<String,Object> context,List<Object> sources){
        store.check(p);validate(name,b);
        if("get_my_profile".equals(name)){Map<String,Object> r=db.one("SELECT p.gender gender,TIMESTAMPDIFF(YEAR,p.birth_date,UTC_DATE()) age,p.organization_name organization,p.team_name team,p.position_name position,p.exposure_history occupationalExposure FROM a_health_records r JOIN a_employee_roster_profiles p ON p.employee_id=r.employee_id AND p.scope_code=r.scope_code AND p.data_mode=r.data_mode WHERE r.record_id=? AND r.scope_code=? AND r.data_mode=? AND p.deleted_at IS NULL",p.record,p.scope,p.mode);require(r!=null,403,"职工档案已停用");return r;}
        if("list_my_reports".equals(name)){String where=" FROM a_health_reports h JOIN a_report_series s ON s.report_id=h.report_id AND s.current_revision=h.revision WHERE h.record_id=? AND h.scope_code=? AND h.data_mode=?";int page=num(b.get("page"));return map("total",db.count("SELECT COUNT(*)"+where,p.record,p.scope,p.mode),"page",page,"pageSize",20,"items",db.all("SELECT h.report_id reportId,h.revision,h.review_status reviewStatus,h.exam_date_verified examDate,h.exam_date_raw examDateRaw,h.institution_raw institution,EXISTS(SELECT 1 FROM a_report_publications pub WHERE pub.report_id=h.report_id AND pub.revision=h.revision AND pub.record_id=h.record_id) published"+where+" ORDER BY h.created_at DESC,h.report_id LIMIT 20 OFFSET ?",p.record,p.scope,p.mode,(page-1)*20));}
        if("get_my_report".equals(name)){String rid=text(b,"report_id");int rev=num(b.get("revision"));Map<String,Object> h=ehr.rawReport(p.actor,rid,rev,false);require("confirmed".equals(h.get("review_status"))||(!"rejected".equals(h.get("review_status"))&&selected(context,rid,rev)),403,"CANDIDATE_SELECTION_REQUIRED：此报告未审核，请先在页面选中本人报告再解读");Map<String,Object> r=ehr.report(p.actor,rid,rev,true);List<Map<String,Object>> all=(List<Map<String,Object>>)r.get("items");int from=Math.min(all.size(),(num(b.get("page"))-1)*60);List<Map<String,Object>> items=all.subList(from,Math.min(from+60,all.size()));Set<Object> pages=new TreeSet<>();for(Map<String,Object> item:items)if(item.get("page")!=null)pages.add(item.get("page"));for(String kind:new String[]{"conclusions","advice"})for(Map<String,Object> row:(List<Map<String,Object>>)r.get(kind))if(row.get("page")!=null)pages.add(row.get("page"));source(p,rid,rev,pages,sources);return map("reportId",rid,"revision",rev,"examDate",r.get("examDate"),"examDateRaw",r.get("examDateRaw"),"institution",r.get("institution"),"reviewStatus",r.get("reviewStatus"),"candidate",!"confirmed".equals(r.get("reviewStatus")),"conclusions",r.get("conclusions"),"advice",r.get("advice"),"items",items,"totalItems",all.size(),"page",b.get("page"),"pageSize",60,"hasMore",from+items.size()<all.size());}
        if("get_my_health_trends".equals(name)||"get_my_abnormal_items".equals(name)){
            boolean trends="get_my_health_trends".equals(name);String indicator=text(b,"indicator");require(!trends||!indicator.isEmpty(),422,"趋势分析需要指定检查项目");
            String where=" FROM a_health_items i JOIN a_health_reports h ON h.report_id=i.report_id AND h.revision=i.revision JOIN a_report_series s ON s.report_id=h.report_id AND s.current_revision=h.revision JOIN a_report_evidence e ON e.evidence_id=i.primary_evidence_id AND e.report_id=i.report_id AND e.revision=i.revision WHERE h.record_id=? AND h.scope_code=? AND h.data_mode=?";
            List<Object> args=new ArrayList<>(Arrays.asList(p.record,p.scope,p.mode));
            if(trends)where+=" AND h.review_status='confirmed' AND h.exam_date_verified IS NOT NULL";
            else{where+=" AND (h.review_status='confirmed' OR (h.report_id=? AND h.revision=? AND h.review_status<>'rejected')) AND (TRIM(i.abnormal_flag_raw) IN ('H','L','HH','LL','↑','↓','+','++','+++','阳性','异常','偏高','偏低') OR i.abnormal_flag_raw REGEXP '升高|降低|偏高|偏低|超标')";args.add(text(context,"reportId"));args.add(context.getOrDefault("revision",0));}
            if(!indicator.isEmpty()){where+=" AND i.original_field_name LIKE ? ESCAPE '!'";args.add("%"+like(indicator)+"%");}
            long total=db.count("SELECT COUNT(*)"+where,args.toArray());List<Object> pageArgs=new ArrayList<>(args);pageArgs.add((num(b.get("page"))-1)*30);
            List<Map<String,Object>> rows=db.all("SELECT h.report_id reportId,h.revision,h.review_status reviewStatus,h.exam_date_verified examDate,h.exam_date_raw examDateRaw,i.original_field_name indicator,i.result_raw value,i.unit_raw unit,i.reference_range_raw referenceRange,i.abnormal_flag_raw abnormal,e.page_number page"+where+" ORDER BY h.exam_date_verified DESC,h.created_at DESC,h.report_id,i.ordinal LIMIT 30 OFFSET ?",pageArgs.toArray());
            for(Map<String,Object> row:rows)source(p,str(row.get("reportId")),num(row.get("revision")),row.get("page")==null?Collections.emptyList():Arrays.asList(row.get("page")),sources);
            return map("total",total,"items",rows,"page",b.get("page"),"pageSize",30,"basis",trends?"仅本人当前版本已确认报告且有核定日期；保留原始单位，不进行跨单位换算或疾病确诊":"仅本人当前版本已有异常标记；缺标记不代表正常，未审核结果是候选");
        }
        if("get_my_confirmed_risks".equals(name)){Map<String,Object> r=db.one("SELECT assessment_id assessmentId,assessment_time assessmentTime,risk_level riskLevel,risk_score score,rule_version ruleVersion FROM a_health_risk_assessments WHERE record_id=? AND scope_code=? AND data_mode=? AND assessment_status='confirmed' ORDER BY assessment_time DESC,assessment_id DESC LIMIT 1",p.record,p.scope,p.mode);if(r==null)return map("assessed",false,"riskLevel","unknown","note","本人尚无已确认风险评估");r.put("assessed",true);List<Map<String,Object>> factors=db.all("SELECT f.factor_name name,f.result_raw value,f.reason,h.report_id reportId,h.revision,e.page_number page FROM a_health_risk_factors f JOIN a_health_reports h ON h.report_id=f.report_id AND h.revision=f.revision JOIN a_report_evidence e ON e.evidence_id=f.evidence_id AND e.report_id=h.report_id AND e.revision=h.revision WHERE f.assessment_id=? AND h.record_id=? AND h.scope_code=? AND h.data_mode=? AND h.review_status='confirmed' LIMIT 30",r.get("assessmentId"),p.record,p.scope,p.mode);r.put("factors",factors);for(Map<String,Object> f:factors)source(p,str(f.get("reportId")),num(f.get("revision")),Arrays.asList(f.get("page")),sources);return r;}
        throw new EhrException(403,"个人健康师未开放此工具");
    }
}
